// Generar ID de reserva
const dbResult = $node['Guardar en Neon DB'].json;
const reservationId = `RES-${new Date().toISOString().split('T')[0].replace(/-/g, '')}-${String(dbResult.id).padStart(3, '0')}`;

const data = $node['Normalizar Datos'].json;

return [{
  json: {
    reservationId: reservationId,
    nombre: data.nombre,
    email: data.email,
    telefono: data.telefono,
    fecha: data.fechaFormateada,
    hora: data.horaFormateada,
    pax: data.pax,
    total: data.precioTotal,
    deposito: data.depositoAmount,
    tipoEvento: data.tipoEvento,
    calendarEventId: $node['Crear Evento Calendar'].json.id || '',
    dbId: dbResult.id
  }
}];

